                      petsAPI
                        .submitPetRequest(foundFormData)
                        .then((response) => {
                          if (response.data.success) {
                            setSuccessMessage(
                              "Found pet report submitted successfully!"
                            );
                            setPetForm({
                              pet_name: "",
                              pet_type: "Dog",
                              pet_breed: "",
                              pet_age: "",
                              pet_colour: "",
                              pet_weight: "",
                              pet_gender: "Male",
                              pet_location: "",
                              pet_state: "",
                              pet_city: "",
                              pet_status: "found",
                              description: "",
                              is_vaccinated: false,
                              is_diseased: false,
                              vaccination_details: "",
                              health_conditions: "",
                            });
                            loadData();
                            setTimeout(() => setActiveTab("dashboard"), 2000);
                          }
                        })
                        .catch((err) => {
                          setError(
                            err.response?.data?.error ||
                              "Failed to submit found pet report. Please try again."
