                    <span className="text-3xl bg-gradient-to-r from-primary-blue via-primary-teal to-accent-yellow bg-clip-text text-transparent">
                      🔍
                    </span>
                    <span className="bg-gradient-to-r from-primary-blue via-primary-teal to-accent-yellow bg-clip-text text-transparent">
                      ALL APPROVED LOST PETS (
                      {
                        allLostReports.filter(
                          (r) =>
                            r.report_type === "LOST" &&
                            r.report_status === "ACCEPTED"
                        ).length
                      }
                      )
                    </span>
                  </h2>
                  <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    <>
                    {loading ? (
                      <div className="col-span-full flex flex-col items-center justify-center py-12">
                        <div className="animate-spin rounded-full h-16 w-16 border-b-4 border-primary-blue mb-4"></div>
                        <p className="text-gray-600 dark:text-white">
                          Loading approved lost pet reports...
                        </p>
                      </div>
                    ) : allLostReports.filter(
                        (r) =>
                          r.report_type === "LOST" &&
                          r.report_status === "ACCEPTED"
                      ).length > 0 ? (
                      allLostReports
                        .filter(
                          (r) =>
                            r.report_type === "LOST" &&
                            r.report_status === "ACCEPTED"
                        )
                        .map((report) => (
                          <div
                            key={report.id}
                            className="bg-gradient-to-br from-slate-50 to-blue-50 dark:from-slate-800 dark:to-slate-700 rounded-2xl shadow-lg hover:shadow-2xl transition-all duration-300 transform hover:-translate-y-2 overflow-hidden border border-blue-100 dark:border-slate-600"
                          >
                            <div className="relative h-56 overflow-hidden bg-gradient-to-br from-gray-100 to-gray-200">
                              <img
                                src={getImageUrl(report.photo)}
                                alt={report.pet_name}
                                onError={(e) => {
                                  e.target.src = "/default-pet.png";
                                }}
                                className="w-full h-full object-cover"
                              />
                              {/* Favourite toggle (top-right) for lost report if pet id exists */}
                              {report.pet_id && (
                                <button
                                  onClick={async (e) => {
                                    e.stopPropagation();
                                    const fav = findFavouriteByPetId(report.pet_id);
                                    if (fav) await handleRemoveFavourite(fav.id);
                                    else await handleAddFavourite(report.pet_id);
                                  }}
                                  title={findFavouriteByPetId(report.pet_id) ? "Remove favourite" : "Add to favourites"}
                                  aria-pressed={!!findFavouriteByPetId(report.pet_id)}
                                  className={`absolute top-3 right-3 z-10 p-2 rounded-full shadow-md transition-colors ${findFavouriteByPetId(report.pet_id) ? 'bg-pink-500 text-white' : 'bg-white text-gray-800 dark:bg-slate-700 dark:text-white'}`}
                                >
                                  <span className="material-icons">favorite</span>
                                </button>
                              )}
                              <div className="absolute bottom-0 left-0 right-0 bg-gradient-to-t from-black/70 to-transparent p-4">
                                <h3 className="text-white text-xl font-bold">
                                  {report.pet_name}
                                </h3>
