                          <label className="text-sm font-semibold text-gray-700 dark:text-white mb-2">
                            Health Condition Description
                          </label>
                          <textarea
                            rows="3"
                            value={postAdoptionForm.disease_description}
                            onChange={(e) =>
                              setPostAdoptionForm({
                                ...postAdoptionForm,
                                disease_description: e.target.value,
                              })
                            }
                            className="w-full px-4 py-3 border-2 border-gray-200 dark:border-slate-600 rounded-xl focus:border-primary-blue dark:bg-slate-700 dark:text-white focus:outline-none transition-colors resize-none"
                            placeholder="Describe any health conditions or special care needs..."
                          />
                        </div>
                      )}
                    </div>

                    <button
                      type="submit"
                      disabled={submitLoading}
                      className="w-full px-6 py-4 bg-gradient-to-r from-primary-blue via-primary-teal to-accent-yellow text-white font-bold rounded-xl hover:shadow-lg hover:scale-105 transition-all duration-200 disabled:opacity-50 disabled:cursor-not-allowed disabled:hover:scale-100 disabled:hover:shadow-none"
                    >
                      {submitLoading ? (
                        <span className="flex items-center justify-center gap-2">
                          <svg
                            className="animate-spin h-5 w-5"
                            viewBox="0 0 24 24"
                          >
                            <circle
                              className="opacity-25"
                              cx="12"
                              cy="12"
                              r="10"
                              stroke="currentColor"
                              strokeWidth="4"
                              fill="none"
                            />
                            <path
                              className="opacity-75"
                              fill="currentColor"
                              d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
                            />
                          </svg>
                          Posting...
                        </span>
                      ) : (
                        "Post Pet for Adoption"
                      )}
                    </button>
                  </form>
                </div>
              )}

              {activeTab === "my-adoption-posts" && (
                <div className="my-adoption-posts-section">
                  <div className="section-header">
                    <span className="material-icons">article</span>
                    MY ADOPTION POSTS ({myAdoptionPosts.length})
                  </div>
                  <div className="reports-grid">
                    {loading ? (
                      <div className="loading">
                        Loading your adoption posts...
                      </div>
                    ) : myAdoptionPosts.length > 0 ? (
                      myAdoptionPosts.map((post) => (
                        <div
                          key={post.id}
                          className="dashboard-pet-card my-adoption-post"
                        >
                          <div className="pet-card-image">
                            <img
                              src={getImageUrl(post.image)}
                              alt={post.name}
                              onError={(e) => {
                                e.target.src = "/default-pet.png";
                              }}
                            />
                            <div className="pet-name-overlay">
                              <h3>{post.name}</h3>
                            </div>
                          </div>
                          <div className="pet-card-info">
                            <div className="pet-type">{post.type}</div>
                            <div className="pet-details">
                              {post.breed && (
                                <span className="pet-breed">{post.breed}</span>
                              )}
                              <span className="pet-age">
                                🎂 {post.age} years old
                              </span>
                              <span className="pet-gender">
                                {post.gender === "Male" ? "♂️" : "♀️"}{" "}
                                {post.gender}
                              </span>
                              {post.location && (
                                <span className="pet-location">
                                  📍 {post.location}
                                </span>
                              )}
                            </div>
                            <div className="pet-description">
                              {post.description
                                ? post.description.length > 100
                                  ? `${post.description.substring(0, 100)}...`
                                  : post.description
                                : "No description available"}
                            </div>
                            <div className="pet-medical-info">
                              {post.is_vaccinated && (
                                <span className="badge vaccinated">
                                  ✓ Vaccinated
                                </span>
                              )}
                              {post.is_diseased && (
                                <span className="badge health-issue">
                                  ⚠ Health Condition
                                </span>
                              )}
                            </div>
                            <div
                              className={`pet-status-badge status-${post.report_status}`}
                            >
                              {post.report_status === "pending" &&
                                "⏳ PENDING ADMIN REVIEW"}
                              {post.report_status === "accepted" &&
                                "✅ APPROVED - LIVE"}
                              {post.report_status === "rejected" &&
                                "❌ REJECTED"}
                            </div>
                            {post.admin_comment && (
                              <div className="admin-comment">
                                <strong>Admin Comment:</strong>{" "}
                                {post.admin_comment}
                              </div>
                            )}
                            <div className="post-date">
                              Posted:{" "}
                              {new Date(post.created_at).toLocaleDateString()}
                            </div>
                          </div>
                        </div>
                      ))
                    ) : (
                      <div className="no-reports">
                        <span className="material-icons">article</span>
                        <p>You haven't posted any pets for adoption yet</p>
                      </div>
                    )}
                  </div>
                </div>
              )}

              {activeTab === "profile" && (
    <div className="bg-gradient-to-br from-white to-purple-50 dark:from-slate-800 dark:to-slate-700 rounded-2xl shadow-xl p-8 border-2 border-purple-200 dark:border-slate-600">
        <div className="flex items-center gap-3 mb-6">
            <span className="material-icons text-3xl text-primary-blue">
                person
            </span>
            <h2 className="text-2xl font-bold bg-gradient-to-r from-primary-blue via-primary-teal to-accent-yellow bg-clip-text text-transparent">
                PROFILE MANAGEMENT
            </h2>
        </div>

        <div className="grid md:grid-cols-3 gap-8">
            {/* Profile Image Section */}
            <div className="md:col-span-1 flex flex-col items-center">
                <div className="relative w-48 h-48 mb-6">
                    {profileImagePreview ? (
                        <img
                            src={profileImagePreview}
                            alt="Profile"
                            className="w-full h-full rounded-full object-cover border-4 border-primary-blue shadow-xl"
                        />
                    ) : (
                        <div className="w-full h-full rounded-full bg-gradient-to-br from-blue-100 to-teal-100 flex items-center justify-center border-4 border-primary-blue shadow-xl">
                            <span className="material-icons text-6xl text-primary-blue">
                                person
                            </span>
                        </div>
                    )}
                </div>

                {isEditingProfile && (
                    <div className="w-full">
                        <label
                            htmlFor="profile-image-input"
                            className="flex items-center justify-center gap-2 px-4 py-3 bg-gradient-to-r from-primary-blue to-primary-teal text-white rounded-xl cursor-pointer hover:shadow-lg transform hover:scale-105 transition-all duration-200"
                        >
                            <span className="material-icons">photo_camera</span>
                            <span className="font-semibold">Change Photo</span>
                        </label>
                        <input
                            id="profile-image-input"
                            type="file"
                            accept="image/*"
                            onChange={handleProfileImageChange}
                            className="hidden"
                        />
                    </div>
                )}
            </div>

            {/* Profile Details Section */}
            <div className="md:col-span-2">
                <div className="bg-gradient-to-br from-white to-blue-50 dark:from-slate-800 dark:to-slate-700 rounded-2xl p-6 shadow-lg border border-blue-100 dark:border-slate-600 mb-6">
                    <div className="flex items-start justify-between mb-6">
                        <div>
                            <h3 className="text-2xl font-bold text-gray-800 dark:text-white">
                                {profileData.first_name}{" "}
                                {profileData.last_name || user?.username}
                            </h3>
                            <p className="text-gray-500 dark:text-slate-300 mt-1">
                                {profileData.email}
                            </p>
                        </div>

                        {!isEditingProfile ? (
                            <button
                                className="flex items-center gap-2 px-4 py-2 bg-gradient-to-r from-primary-blue to-primary-teal text-white rounded-xl hover:shadow-lg transform hover:scale-105 transition-all duration-200"
                                onClick={() => setIsEditingProfile(true)}
                            >
                                <span className="material-icons text-sm">
                                    edit
                                </span>
                                <span className="font-semibold">
                                    Edit Profile
                                </span>
                            </button>
                        ) : (
                            <div className="flex gap-2">
                                <button
                                    className="flex items-center gap-2 px-4 py-2 bg-gradient-to-r from-green-500 to-green-600 text-white rounded-xl hover:shadow-lg transform hover:scale-105 transition-all duration-200 disabled:opacity-50 disabled:cursor-not-allowed"
                                    onClick={handleProfileSubmit}
                                    disabled={submitLoading}
                                >
                                    <span className="material-icons text-sm">
                                        save
                                    </span>
                                    <span className="font-semibold">
                                        {submitLoading ? "Saving..." : "Save"}
                                    </span>
                                </button>
                                <button
                                    className="flex items-center gap-2 px-4 py-2 bg-gradient-to-r from-red-500 to-red-600 text-white rounded-xl hover:shadow-lg transform hover:scale-105 transition-all duration-200"
                                    onClick={() => {
                                        setIsEditingProfile(false);
                                        setProfileImage(null);
                                        setProfileImagePreview(
                                            getImageUrl(profileData.profile_picture)
                                        );
                                    }}
                                >
                                    <span className="material-icons text-sm">
                                        cancel
                                    </span>
                                    <span className="font-semibold">Cancel</span>
                                </button>
                            </div>
                        )}
                    </div>

                    {isEditingProfile ? (
                        <form
                            onSubmit={handleProfileSubmit}
                            className="space-y-4"
                        >
                            <div className="grid md:grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-sm font-semibold text-gray-700 dark:text-white mb-2">
                                        First Name
                                    </label>
                                    <input
                                        type="text"
                                        name="first_name"
                                        value={profileData.first_name}
                                        onChange={handleProfileInputChange}
                                        placeholder="Enter first name"
                                        className="w-full px-4 py-3 rounded-xl border-2 border-blue-200 dark:border-slate-600 focus:border-primary-blue focus:ring-2 focus:ring-primary-blue/20 dark:bg-slate-700 dark:text-white outline-none transition-all duration-200"
                                    />
                                </div>
                                <div>
                                    <label className="block text-sm font-semibold text-gray-700 dark:text-white mb-2">
                                        Last Name
                                    </label>
                                    <input
                                        type="text"
                                        name="last_name"
                                        value={profileData.last_name}
                                        onChange={handleProfileInputChange}
                                        placeholder="Enter last name"
                                        className="w-full px-4 py-3 rounded-xl border-2 border-blue-200 dark:border-slate-600 focus:border-primary-blue focus:ring-2 focus:ring-primary-blue/20 dark:bg-slate-700 dark:text-white outline-none transition-all duration-200"
                                    />
                                </div>
                            </div>

                            <div className="grid md:grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-sm font-semibold text-gray-700 dark:text-white mb-2">
                                        Email
                                    </label>
                                    <input
                                        type="email"
                                        name="email"
                                        value={profileData.email}
                                        onChange={handleProfileInputChange}
                                        placeholder="Enter email address"
                                        className="w-full px-4 py-3 rounded-xl border-2 border-blue-200 dark:border-slate-600 focus:border-primary-blue focus:ring-2 focus:ring-primary-blue/20 dark:bg-slate-700 dark:text-white outline-none transition-all duration-200"
                                    />
                                </div>
                                <div>
                                    <label className="block text-sm font-semibold text-gray-700 dark:text-white mb-2">
                                        Phone Number
                                    </label>
                                    <input
                                        type="tel"
                                        name="phone_no"
                                        value={profileData.phone_no}
                                        onChange={handleProfileInputChange}
                                        placeholder="Enter phone number"
                                        className="w-full px-4 py-3 rounded-xl border-2 border-blue-200 dark:border-slate-600 focus:border-primary-blue focus:ring-2 focus:ring-primary-blue/20 dark:bg-slate-700 dark:text-white outline-none transition-all duration-200"
                                    />
                                </div>
                            </div>

                            <div className="grid md:grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-sm font-semibold text-gray-700 dark:text-white mb-2">
                                        City
                                    </label>
                                    <input
                                        type="text"
                                        name="city"
                                        value={profileData.city}
                                        onChange={handleProfileInputChange}
                                        placeholder="Enter city"
                                        className="w-full px-4 py-3 rounded-xl border-2 border-blue-200 dark:border-slate-600 focus:border-primary-blue focus:ring-2 focus:ring-primary-blue/20 dark:bg-slate-700 dark:text-white outline-none transition-all duration-200"
                                    />
                                </div>
                                <div>
                                    <label className="block text-sm font-semibold text-gray-700 dark:text-white mb-2">
                                        State
                                    </label>
                                    <input
                                        type="text"
                                        name="state"
                                        value={profileData.state}
                                        onChange={handleProfileInputChange}
                                        placeholder="Enter state"
                                        className="w-full px-4 py-3 rounded-xl border-2 border-blue-200 dark:border-slate-600 focus:border-primary-blue focus:ring-2 focus:ring-primary-blue/20 dark:bg-slate-700 dark:text-white outline-none transition-all duration-200"
                                    />
                                </div>
                            </div>

                            <div className="grid md:grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-sm font-semibold text-gray-700 dark:text-white mb-2">
                                        PIN Code
                                    </label>
                                    <input
                                        type="text"
                                        name="pincode"
                                        value={profileData.pincode}
                                        onChange={handleProfileInputChange}
                                        placeholder="Enter PIN code"
                                        className="w-full px-4 py-3 rounded-xl border-2 border-blue-200 dark:border-slate-600 focus:border-primary-blue focus:ring-2 focus:ring-primary-blue/20 dark:bg-slate-700 dark:text-white outline-none transition-all duration-200"
                                    />
                                </div>
                                <div>
                                    <label className="block text-sm font-semibold text-gray-700 dark:text-white mb-2">
                                        Gender
                                    </label>
                                    <select
                                        name="gender"
                                        value={profileData.gender}
                                        onChange={handleProfileInputChange}
                                        className="w-full px-4 py-3 rounded-xl border-2 border-blue-200 dark:border-slate-600 focus:border-primary-blue focus:ring-2 focus:ring-primary-blue/20 dark:bg-slate-700 dark:text-white outline-none transition-all duration-200 bg-white dark:bg-slate-700"
                                    >
                                        <option value="">Select Gender</option>
                                        <option value="Male">Male</option>
                                        <option value="Female">Female</option>
                                        <option value="Other">Other</option>
                                    </select>
                                </div>
                            </div>

                            <div>
                                <label className="block text-sm font-semibold text-gray-700 dark:text-white mb-2">
                                    Address
                                </label>
                                <textarea
                                    name="address"
                                    value={profileData.address}
                                    onChange={handleProfileInputChange}
                                    placeholder="Enter complete address"
                                    rows="3"
                                    className="w-full px-4 py-3 rounded-xl border-2 border-blue-200 dark:border-slate-600 focus:border-primary-blue focus:ring-2 focus:ring-primary-blue/20 dark:bg-slate-700 dark:text-white outline-none transition-all duration-200 resize-none"
                                />
                            </div>
                        </form>
                    ) : (
                        // PROFESSIONAL STACKED PROFILE VIEW (REPLACED METRIC CARDS)
                        <div className="space-y-4">
                            {/* Phone Number */}
                            <div className="border-b border-blue-100 dark:border-slate-600 pb-2">
                                <span className="flex items-center gap-2 text-sm font-semibold text-primary-blue dark:text-blue-300 uppercase tracking-wide">
                                    <span className="material-icons text-lg">phone</span>
                                    Phone Number
                                </span>
                                <p className="text-lg text-gray-800 dark:text-white ml-6 mt-1">
                                    {profileData.phone_no || "Not provided"}
                                </p>
                            </div>

                            {/* City & State */}
                            <div className="grid grid-cols-2 gap-4">
                                <div className="border-b border-blue-100 dark:border-slate-600 pb-2">
                                    <span className="flex items-center gap-2 text-sm font-semibold text-primary-blue dark:text-blue-300 uppercase tracking-wide">
                                        <span className="material-icons text-lg">location_city</span>
                                        City
                                    </span>
                                    <p className="text-lg text-gray-800 dark:text-white ml-6 mt-1">
                                        {profileData.city || "Not provided"}
                                    </p>
                                </div>
                                <div className="border-b border-blue-100 dark:border-slate-600 pb-2">
                                    <span className="flex items-center gap-2 text-sm font-semibold text-primary-blue dark:text-blue-300 uppercase tracking-wide">
                                        <span className="material-icons text-lg">public</span>
                                        State
                                    </span>
                                    <p className="text-lg text-gray-800 dark:text-white ml-6 mt-1">
                                        {profileData.state || "Not provided"}
                                    </p>
                                </div>
                            </div>
                            
                            {/* PIN Code & Gender */}
                            <div className="grid grid-cols-2 gap-4">
                                <div className="border-b border-blue-100 dark:border-slate-600 pb-2">
                                    <span className="flex items-center gap-2 text-sm font-semibold text-primary-blue dark:text-blue-300 uppercase tracking-wide">
                                        <span className="material-icons text-lg">local_post_office</span>
                                        PIN Code
                                    </span>
                                    <p className="text-lg text-gray-800 dark:text-white ml-6 mt-1">
                                        {profileData.pincode || "Not provided"}
                                    </p>
                                </div>
                                <div className="border-b border-blue-100 dark:border-slate-600 pb-2">
                                    <span className="flex items-center gap-2 text-sm font-semibold text-primary-blue dark:text-blue-300 uppercase tracking-wide">
                                        <span className="material-icons text-lg">face</span>
                                        Gender
                                    </span>
                                    <p className="text-lg text-gray-800 dark:text-white ml-6 mt-1">
                                        {profileData.gender || "Not provided"}
                                    </p>
                                </div>
                            </div>

                            {/* Address */}
                            <div className="pt-2">
                                <span className="flex items-center gap-2 text-sm font-semibold text-primary-blue dark:text-blue-300 uppercase tracking-wide">
                                    <span className="material-icons text-lg">home</span>
                                    Address
                                </span>
                                <p className="text-lg text-gray-800 dark:text-white ml-6 mt-1 whitespace-pre-wrap">
                                    {profileData.address || "Not provided"}
                                </p>
                            </div>
                        </div>
                    )}
                </div>
            </div>
        </div>
    </div>
)}
      {/* Floating Feedback button & Modal placed here near the end of main content */}
      <div>
        <button
          onClick={() => setShowFeedbackModal(true)}
          className="fixed bottom-6 right-6 z-50 bg-purple-900 text-white p-3 rounded-full shadow-lg hover:scale-105 transition-transform"
          title="Give Feedback"
        >
          <span className="material-icons">feedback</span>
        </button>

        {showFeedbackModal && (
          <div className="fixed inset-0 bg-black/60 z-60 flex items-center justify-center p-4">
            <div className={`max-w-3xl w-full rounded-2xl overflow-auto p-6 ${isDarkMode ? 'bg-gray-900 text-white' : 'bg-white text-gray-900'} shadow-2xl`}
              onClick={() => setShowFeedbackModal(false)}>
              <div onClick={(e) => e.stopPropagation()}>
                <div className="flex items-center justify-between mb-4">
                  <h3 className="text-2xl font-bold">Community Feedback</h3>
                  <button onClick={() => setShowFeedbackModal(false)} className="p-2 rounded-full hover:bg-gray-200 dark:hover:bg-gray-800">
                    <span className="material-icons">close</span>
                  </button>
                </div>

                <form onSubmit={handleSubmit} className="mb-4">
                  <div className="mb-3">
                    <input id="feedback-file-input" type="file" accept="image/*" onChange={handleFileChange} />
                  </div>
                  <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 mb-4">
                    <input placeholder="Your name (optional)" value={name} onChange={(e) => setName(e.target.value)} className="p-2 rounded border" />
                    <textarea placeholder="Write your feedback..." value={message} onChange={(e) => setMessage(e.target.value)} className="sm:col-span-2 p-2 rounded border min-h-[100px]" />
                  </div>
                  <div className="flex gap-3">
                    <button type="submit" className="px-4 py-2 bg-purple-900 text-white rounded" disabled={submitting}>{submitting ? 'Sending...' : 'Send Feedback'}</button>
                    <button type="button" className="px-4 py-2 border rounded" onClick={() => { setName(''); setMessage(''); setError(''); }}>Clear</button>
                  </div>
                </form>

                <div>
                  {loading ? (<div className="text-center py-8">Loading feedback…</div>) : feedbacks.length === 0 ? (
                    <div className="text-center py-8 text-gray-600">No feedback yet — be the first!</div>
                  ) : (
                    <ul className="space-y-4">
                      {feedbacks.map((f) => (
                        <li key={f.id} className="p-4 border rounded">
                          <div className="flex items-center gap-3 mb-2">
                            {f.image ? <img src={f.image} alt="User" className="w-10 h-10 rounded-full object-cover" /> : <div className="w-10 h-10 rounded-full bg-purple-200 flex items-center justify-center">{f.name ? f.name[0].toUpperCase() : 'A'}</div>}
                            <div>
                              <div className="font-bold">{f.name || 'Anonymous'}</div>
                              <div className="text-xs text-gray-500">{new Date(f.created_at).toLocaleString()}</div>
                            </div>
                          </div>
                          <p className="whitespace-pre-line">{f.message}</p>
                        </li>
                      ))}
                    </ul>
                  )}
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
{/* Feedback area - CORRECTLY ADDED OUTSIDE THE HEADER */}
          <section className="mt-16 pt-6 border-t border-gray-300 dark:border-slate-700">
            <div className="max-w-4xl mx-auto">
              <h3 className="text-3xl font-extrabold mb-6 text-purple-900 dark:text-purple-400">
                Community Feedback
              </h3>

{/* Form */}
<form
  onSubmit={handleSubmit}
  className={`p-6 rounded-lg shadow mb-6 transition-colors duration-300 ${
    isDarkMode
      ? "bg-gray-900 text-white border border-gray-700"
      : "bg-gray-50 text-purple-900 border border-purple-200"
  }`}
>
  {/* Error Message */}
  {error && (
    <div
      className={`text-sm mb-3 ${
        isDarkMode ? "text-red-400" : "text-red-600"
      }`}
    >
      {error}
    </div>
  )}

  {/* File Upload */}
  <div className="mb-6">
    <label className="block font-semibold mb-2">
      Upload Image (optional)
    </label>
    <input
      id="feedback-file-input"
      type="file"
      accept="image/*"
      onChange={handleFileChange}
      className={`w-full px-4 py-3 rounded-xl transition-colors duration-300 ${
        isDarkMode
          ? "bg-gray-800 text-white border border-gray-600 focus:border-white focus:ring-white"
          : "bg-purple-50 text-purple-900 border border-purple-200 focus:border-purple-500 focus:ring-purple-200"
      }`}
    />
  </div>

  {/* Name and Message */}
  <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 mb-4">
    <input
      className={`sm:col-span-1 p-2 rounded border transition-colors duration-300 ${
        isDarkMode
          ? "bg-gray-800 text-white border-gray-600 focus:border-white focus:ring-white"
          : "bg-purple-50 text-purple-900 border-purple-200 focus:border-purple-500 focus:ring-purple-200"
      }`}
      placeholder="Your name (optional)"
      value={name}
      onChange={(e) => setName(e.target.value)}
    />
    <textarea
      className={`sm:col-span-2 p-2 rounded border resize-y min-h-[100px] transition-colors duration-300 ${
        isDarkMode
          ? "bg-gray-800 text-white border-gray-600 focus:border-white focus:ring-white"
          : "bg-purple-50 text-purple-900 border-purple-200 focus:border-purple-500 focus:ring-purple-200"
      }`}
      placeholder="Write your feedback..."
      value={message}
      onChange={(e) => setMessage(e.target.value)}
    />
  </div>

  {/* Buttons */}
  <div className="flex items-center gap-4">
    <button
      type="submit"
      className={`px-4 py-2 rounded transition-colors duration-300 ${
        isDarkMode
          ? "bg-white text-gray-900 hover:bg-gray-200"
          : "bg-purple-900 text-white hover:bg-purple-700"
      }`}
      disabled={submitting}
    >
      {submitting ? "Sending..." : "Send Feedback"}
    </button>
    <button
      type="button"
      className={`px-4 py-2 border rounded transition-colors duration-300 ${
        isDarkMode
          ? "border-gray-600 text-gray-300 hover:bg-gray-800"
          : "border-gray-300 text-gray-700 hover:bg-gray-100"
      }`}
      onClick={() => {
        setName("");
        setMessage("");
        setError("");
      }}
    >
      Clear
    </button>
  </div>
</form>

{/* Feedback List */}
<div className={`transition-colors duration-300 ${isDarkMode ? "text-white" : "text-gray-900"}`}>
  {loading ? (
    <div className="text-center py-8">Loading feedback…</div>
  ) : feedbacks.length === 0 ? (
    <div className={`text-center py-8 ${isDarkMode ? "text-gray-400" : "text-gray-600"}`}>
      No feedback yet — be the first!
    </div>
  ) : (
    <ul className="space-y-4">
      {feedbacks.map((f) => {
        const messageTooLong = f.message && f.message.length > 120;
        const isExpanded = expandedItems[f.id] || false;
        const displayMessage = isExpanded
          ? f.message
          : messageTooLong
          ? f.message.slice(0, 120) + "..."
          : f.message;

        return (
          <li
            key={f.id}
            className={`rounded-xl shadow-md p-6 hover:shadow-lg transition duration-300 border ${
              isDarkMode
                ? "bg-gray-800 border-gray-700"
                : "bg-white border-purple-100"
            }`}
          >
            <div className="flex items-start justify-between mb-3">
              <div className="flex items-center gap-3">
                {f.image ? (
                  <img
                    src={f.image}
                    alt="User"
                    className="w-12 h-12 rounded-full object-cover border-2 border-purple-300"
                  />
                ) : (
                  <div className="w-12 h-12 rounded-full bg-purple-200 flex items-center justify-center text-purple-800 font-bold">
                    {f.name ? f.name.charAt(0).toUpperCase() : "A"}
                  </div>
                )}

                <div>
                  <div className={`font-bold ${isDarkMode ? "text-purple-400" : "text-purple-900"}`}>
                    {f.name || "Anonymous"}
                  </div>
                  <span className={`text-xs ${isDarkMode ? "text-gray-500" : "text-gray-400"}`}>
                    {new Date(f.created_at).toLocaleString()}
                  </span>
                </div>
              </div>
            </div>

            {/* Message with read more toggle */}
            <p className={`mt-3 whitespace-pre-line ${isDarkMode ? "text-gray-300" : "text-gray-700"}`}>
              {displayMessage}
            </p>

            {messageTooLong && (
              <button
                onClick={() =>
                  setExpandedItems((prev) => ({
                    ...prev,
                    [f.id]: !prev[f.id],
                  }))
                }
                className="mt-2 text-sm text-purple-700 hover:underline"
              >
                {isExpanded ? "Read less" : "Read more"}
              </button>
            )}
          </li>
        );
      })}
    </ul>
  )}
</div>

            </div>
          </section>
            </main>
          </div>
        </div>

        {/* Pet Detail Modal */}
        {showDetailModal && (
          <div
            className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[100] flex items-center justify-center p-4 animate-fadeIn"
            onClick={closeDetailModal}
          >
            <div
              className="bg-gradient-to-br from-white to-blue-50 dark:from-slate-800 dark:to-slate-700 rounded-3xl shadow-2xl max-w-4xl w-full max-h-[90vh] overflow-y-auto relative animate-slideUp border dark:border-slate-600"
              onClick={(e) => e.stopPropagation()}
            >
              {/* Close Button */}
              <button
                onClick={closeDetailModal}
                className="absolute top-4 right-4 z-10 bg-white/90 dark:bg-slate-700/90 hover:bg-red-500 text-gray-600 dark:text-white hover:text-white rounded-full p-2 shadow-lg transition-all duration-300 transform hover:scale-110"
              >
                <span className="material-icons">close</span>
              </button>

              {detailLoading ? (
                <div className="flex items-center justify-center py-20">
                  <div className="text-center">
                    <div className="inline-block animate-spin rounded-full h-12 w-12 border-b-2 border-primary-blue mb-4"></div>
                    <p className="text-gray-600 dark:text-white">
                      Loading pet details...
                    </p>
                  </div>
                </div>
              ) : selectedPetDetails ? (
                <div className="p-8">
                  {/* Header Section with Image */}
                  <div className="flex flex-col md:flex-row gap-6 mb-6">
                    {/* Pet Image */}
                    <div className="md:w-1/2">
                      <div className="relative rounded-2xl overflow-hidden shadow-xl">
                        <img
                          src={getImageUrl(selectedPetDetails.pet_info.image)}
                          alt={selectedPetDetails.pet_info.name}
                          className="w-full h-96 object-cover"
                          onError={(e) => {
                            e.target.src = "/default-pet.png";
                          }}
                        />
                        <div className="absolute bottom-0 left-0 right-0 bg-gradient-to-t from-black/70 to-transparent p-4">
                          <h2 className="text-3xl font-bold text-white">
                            {selectedPetDetails.pet_info.name}
                          </h2>
                        </div>
                      </div>
                    </div>

                    {/* Quick Info */}
                    <div className="md:w-1/2 space-y-4">
                      <div className="inline-block px-4 py-2 bg-gradient-to-r from-primary-blue to-primary-teal text-white rounded-full text-sm font-semibold shadow-lg">
                        {selectedPetDetails.pet_info.type}
                      </div>

                      <div className="grid grid-cols-2 gap-4">
                        <div className="bg-gradient-to-br from-blue-50 to-blue-100 dark:from-blue-900 dark:to-blue-800 p-4 rounded-xl">
                          <span className="text-xs text-gray-600 dark:text-slate-200 font-semibold">
                            BREED
                          </span>
                          <p className="text-lg font-bold text-gray-800 dark:text-white">
                            {selectedPetDetails.pet_info.breed || "Unknown"}
                          </p>
                        </div>
                        <div className="bg-gradient-to-br from-teal-50 to-teal-100 dark:from-teal-900 dark:to-teal-800 p-4 rounded-xl">
                          <span className="text-xs text-gray-600 dark:text-slate-200 font-semibold">
                            AGE
                          </span>
                          <p className="text-lg font-bold text-gray-800 dark:text-white">
                            {selectedPetDetails.pet_info.age || "Unknown"} years
                          </p>
                        </div>
                        <div className="bg-gradient-to-br from-purple-50 to-purple-100 dark:from-purple-900 dark:to-purple-800 p-4 rounded-xl">
                          <span className="text-xs text-gray-600 dark:text-slate-200 font-semibold">
                            GENDER
                          </span>
                          <p className="text-lg font-bold text-gray-800 dark:text-white">
                            {selectedPetDetails.pet_info.gender || "Unknown"}
                          </p>
                        </div>
                        <div className="bg-gradient-to-br from-pink-50 to-pink-100 dark:from-pink-900 dark:to-pink-800 p-4 rounded-xl">
                          <span className="text-xs text-gray-600 dark:text-slate-200 font-semibold">
                            COLOR
                          </span>
                          <p className="text-lg font-bold text-gray-800 dark:text-white">
                            {selectedPetDetails.pet_info.colour || "Unknown"}
                          </p>
                        </div>
                      </div>

                      <div
                        className={`px-4 py-3 rounded-xl text-center font-semibold ${
                          selectedPetDetails.pet_info.status === "available"
                            ? "bg-green-100 text-green-700 dark:bg-green-800 dark:text-green-100"
                            : selectedPetDetails.pet_info.status === "adopted"
                            ? "bg-blue-100 text-blue-700 dark:bg-blue-800 dark:text-blue-100"
                            : "bg-gray-100 text-gray-700 dark:bg-gray-800 dark:text-white"
                        }`}
                      >
                        {selectedPetDetails.pet_info.status?.toUpperCase()}
                      </div>
                    </div>
                  </div>

                  {/* Description */}
                  <div className="mb-6 bg-gradient-to-br from-slate-50 to-blue-50 dark:from-slate-800 dark:to-slate-700 p-6 rounded-2xl border border-blue-100 dark:border-slate-600">
                    <h3 className="text-xl font-bold text-gray-800 dark:text-white mb-3 flex items-center gap-2">
                      <span className="material-icons text-primary-blue">
                        description
                      </span>
                      Description
                    </h3>
                    <p className="text-gray-700 dark:text-white leading-relaxed">
                      {selectedPetDetails.pet_info.description ||
                        "No description available"}
                    </p>
                  </div>

                  {/* Location Info */}
                  <div className="mb-6 bg-gradient-to-br from-slate-50 to-blue-50 dark:from-slate-800 dark:to-slate-700 p-6 rounded-2xl border border-blue-100 dark:border-slate-600">
                    <h3 className="text-xl font-bold text-gray-800 dark:text-white mb-3 flex items-center gap-2">
                      <span className="material-icons text-primary-teal">
                        location_on
                      </span>
                      Location Details
                    </h3>
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                      <div>
                        <span className="text-sm text-gray-600 dark:text-slate-200 font-semibold">
                          Location
                        </span>
                        <p className="text-gray-800 dark:text-white">
                          {selectedPetDetails.pet_info.location ||
                            "Not specified"}
                        </p>
                      </div>
                      <div>
                        <span className="text-sm text-gray-600 dark:text-slate-200 font-semibold">
                          City
                        </span>
                        <p className="text-gray-800 dark:text-white">
                          {selectedPetDetails.pet_info.city || "Not specified"}
                        </p>
                      </div>
                      <div>
                        <span className="text-sm text-gray-600 dark:text-slate-200 font-semibold">
                          State
                        </span>
                        <p className="text-gray-800 dark:text-white">
                          {selectedPetDetails.pet_info.state || "Not specified"}
                        </p>
                      </div>
                    </div>
                  </div>

                  {/* Medical History */}
                  {selectedPetDetails.medical_history && (
                    <div className="mb-6 bg-gradient-to-br from-green-50 to-green-100 dark:from-green-900 dark:to-green-800 p-6 rounded-2xl border border-green-200 dark:border-green-700">
                      <h3 className="text-xl font-bold text-gray-800 dark:text-white mb-3 flex items-center gap-2">
                        <span className="material-icons text-green-600 dark:text-green-400">
                          medical_services
                        </span>
                        Medical History
                      </h3>
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <div className="bg-gradient-to-br from-white to-blue-50 dark:from-slate-700 dark:to-slate-600 p-4 rounded-xl">
                          <span className="text-sm text-gray-600 dark:text-white font-semibold">
                            Vaccination Status
                          </span>
                          <p className="text-gray-800 dark:text-white flex items-center gap-2 mt-1">
                            {selectedPetDetails.pet_info.is_vaccinated ? (
                              <>
                                <span className="material-icons text-green-600 dark:text-green-400">
                                  check_circle
                                </span>
                                Vaccinated
                              </>
                            ) : (
                              <>
                                <span className="material-icons text-red-600 dark:text-red-400">
                                  cancel
                                </span>
                                Not Vaccinated
                              </>
                            )}
                          </p>
                        </div>
                        <div className="bg-gradient-to-br from-white to-blue-50 dark:from-slate-700 dark:to-slate-600 p-4 rounded-xl">
                          <span className="text-sm text-gray-600 dark:text-white font-semibold">
                            Health Status
                          </span>
                          <p className="text-gray-800 dark:text-white flex items-center gap-2 mt-1">
                            {selectedPetDetails.pet_info.is_diseased ? (
                              <>
                                <span className="material-icons text-orange-600 dark:text-orange-400">
                                  warning
                                </span>
                                Has Health Condition
                              </>
                            ) : (
                              <>
                                <span className="material-icons text-green-600 dark:text-green-400">
                                  check_circle
                                </span>
                                Healthy
                              </>
                            )}
                          </p>
                        </div>
                        {selectedPetDetails.medical_history.vaccine_name && (
                          <div className="bg-gradient-to-br from-white to-blue-50 dark:from-slate-700 dark:to-slate-600 p-4 rounded-xl">
                            <span className="text-sm text-gray-600 dark:text-white font-semibold">
                              Vaccine Name
                            </span>
                            <p className="text-gray-800 dark:text-white mt-1">
                              {selectedPetDetails.medical_history.vaccine_name}
                            </p>
                          </div>
                        )}
                        {selectedPetDetails.medical_history
                          .last_vaccinated_date && (
                          <div className="bg-gradient-to-br from-white to-blue-50 dark:from-slate-700 dark:to-slate-600 p-4 rounded-xl">
                            <span className="text-sm text-gray-600 dark:text-white font-semibold">
                              Last Vaccinated
                            </span>
                            <p className="text-gray-800 dark:text-white mt-1">
                              {new Date(
                                selectedPetDetails.medical_history.last_vaccinated_date
                              ).toLocaleDateString()}
                            </p>
                          </div>
                        )}
                        {selectedPetDetails.medical_history.disease_name && (
                          <div className="bg-gradient-to-br from-white to-blue-50 dark:from-slate-700 dark:to-slate-600 p-4 rounded-xl col-span-2">
                            <span className="text-sm text-gray-600 dark:text-slate-200 font-semibold">
                              Disease/Condition
                            </span>
                            <p className="text-gray-800 dark:text-white mt-1">
                              {selectedPetDetails.medical_history.disease_name}
                            </p>
                            {selectedPetDetails.medical_history.stage && (
                              <p className="text-sm text-gray-600 dark:text-slate-200 mt-1">
                                Stage:{" "}
                                {selectedPetDetails.medical_history.stage}
                              </p>
                            )}
                          </div>
                        )}
                        {selectedPetDetails.medical_history.treatment_name && (
                          <div className="bg-gradient-to-br from-white to-blue-50 dark:from-slate-700 dark:to-slate-600 p-4 rounded-xl col-span-2">
                            <span className="text-sm text-gray-600 dark:text-slate-200 font-semibold">
                              Treatment
                            </span>
                            <p className="text-gray-800 dark:text-white mt-1">
                              {
                                selectedPetDetails.medical_history
                                  .treatment_name
                              }
                            </p>
                          </div>
                        )}
                      </div>
                    </div>
                  )}

                  {/* Physical Details */}
                  <div className="mb-6 bg-gradient-to-br from-slate-50 to-blue-50 dark:from-slate-800 dark:to-slate-700 p-6 rounded-2xl border border-blue-100 dark:border-slate-600">
                    <h3 className="text-xl font-bold text-gray-800 dark:text-white mb-3 flex items-center gap-2">
                      <span className="material-icons text-primary-blue">
                        info
                      </span>
                      Physical Details
                    </h3>
                    <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                      <div>
                        <span className="text-sm text-gray-600 dark:text-slate-200 font-semibold">
                          Weight
                        </span>
                        <p className="text-gray-800 dark:text-white">
                          {selectedPetDetails.pet_info.weight
                            ? `${selectedPetDetails.pet_info.weight} kg`
                            : "Not specified"}
                        </p>
                      </div>
                      <div>
                        <span className="text-sm text-gray-600 dark:text-slate-200 font-semibold">
                          Color
                        </span>
                        <p className="text-gray-800 dark:text-white">
                          {selectedPetDetails.pet_info.colour ||
                            "Not specified"}
                        </p>
                      </div>
                      <div className="col-span-2">
                        <span className="text-sm text-gray-600 dark:text-slate-200 font-semibold">
                          Created
                        </span>
                        <p className="text-gray-800 dark:text-white">
                          {new Date(
                            selectedPetDetails.pet_info.created_at
                          ).toLocaleDateString()}
                        </p>
                      </div>
                    </div>
                  </div>

                  {/* Reports Section */}
                  {selectedPetDetails.reports &&
                    selectedPetDetails.reports.length > 0 && (
                      <div className="mb-6 bg-gradient-to-br from-yellow-50 to-yellow-100 dark:from-yellow-900 dark:to-yellow-800 p-6 rounded-2xl border border-yellow-200 dark:border-yellow-700">
                        <h3 className="text-xl font-bold text-gray-800 dark:text-white mb-3 flex items-center gap-2">
                          <span className="material-icons text-yellow-600 dark:text-yellow-400">
                            report
                          </span>
                          Reports ({selectedPetDetails.total_reports})
                        </h3>
                        <div className="space-y-3">
                          {selectedPetDetails.reports
                            .slice(0, 3)
                            .map((report) => (
                              <div
                                key={report.id}
                                className="bg-gradient-to-br from-white to-blue-50 dark:from-slate-700 dark:to-slate-600 p-4 rounded-xl"
                              >
                                <div className="flex items-center justify-between mb-2">
                                  <span className="font-semibold text-gray-800 dark:text-white">
                                    {report.user_name}
                                  </span>
                                  <span
                                    className={`px-3 py-1 rounded-full text-xs font-semibold ${
                                      report.report_status === "accepted"
                                        ? "bg-green-100 text-green-700 dark:bg-green-800 dark:text-green-100"
                                        : report.report_status === "pending"
                                        ? "bg-yellow-100 text-yellow-700 dark:bg-yellow-800 dark:text-yellow-100"
                                        : "bg-red-100 text-red-700 dark:bg-red-800 dark:text-red-100"
                                    }`}
                                  >
                                    {report.report_status}
                                  </span>
                                </div>
                                <p className="text-sm text-gray-600 dark:text-slate-200">
                                  {report.description}
                                </p>
                                <span className="text-xs text-gray-500 dark:text-slate-300 mt-2 block">
                                  {new Date(
                                    report.created_at
                                  ).toLocaleDateString()}
                                </span>
                              </div>
                            ))}
                        </div>
                      </div>
                    )}

                  {/* Action Buttons */}
                  <div className="flex gap-4 mt-6">
                    <button
                      onClick={closeDetailModal}
                      className="flex-1 px-6 py-3 bg-gradient-to-r from-gray-500 to-gray-600 text-white font-semibold rounded-xl hover:shadow-xl transform hover:scale-105 transition-all duration-300"
                    >
                      Close
                    </button>
                    {selectedPetDetails.pet_info.status === "available" && (
                      <button
                        className="flex-1 px-6 py-3 bg-gradient-to-r from-primary-blue to-primary-teal text-white font-semibold rounded-xl hover:shadow-xl transform hover:scale-105 transition-all duration-300 flex items-center justify-center gap-2"
                        onClick={() => {
                          closeDetailModal();
                          setActiveTab("adopt-pet");
                        }}
                      >
                        <span className="material-icons">favorite</span>
                        Adopt This Pet
                      </button>
                    )}
                  </div>
                </div>
              ) : (
                <div className="flex items-center justify-center py-20">
                  <p className="text-gray-600 dark:text-white">
                    No details available
                  </p>
                </div>
              )}
            </div>
          </div>
        )}

        {/* Notification Detail Modal */}
        {showNotificationModal && selectedNotification && (
          <div
            className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[100] flex items-center justify-center p-4 animate-fadeIn"
            onClick={() => setShowNotificationModal(false)}
          >
            <div
              className="bg-gradient-to-br from-slate-50 to-blue-50 dark:from-slate-800 dark:to-slate-700 rounded-2xl shadow-2xl max-w-2xl w-full max-h-[90vh] overflow-hidden border-2 border-blue-200 dark:border-slate-600 animate-slideUp"
              onClick={(e) => e.stopPropagation()}
            >
              {/* Modal Header */}
              <div className="bg-gradient-to-r from-primary-blue to-primary-teal p-6 border-b border-blue-200 dark:border-slate-600">
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    <span className="material-icons text-white text-3xl">
                      notifications_active
                    </span>
                    <h2 className="text-2xl font-bold text-white">
                      Notification Details
                    </h2>
                  </div>
                  <button
                    onClick={() => setShowNotificationModal(false)}
                    className="p-2 hover:bg-white/20 rounded-full transition-colors"
                  >
                    <span className="material-icons text-white">close</span>
                  </button>
                </div>
              </div>

              {/* Modal Content */}
              <div className="p-6 overflow-y-auto max-h-[calc(90vh-120px)]">
                <div className="space-y-6">
                  {/* Notification Status */}
                  <div className="flex items-center gap-2">
                    <span
                      className={`px-4 py-2 rounded-full text-sm font-semibold ${
                        selectedNotification.is_read
                          ? "bg-gray-200 dark:bg-slate-600 text-gray-700 dark:text-white"
                          : "bg-blue-500 dark:bg-blue-600 text-white"
                      }`}
                    >
                      {selectedNotification.is_read ? "Read" : "Unread"}
                    </span>
                    <span className="text-sm text-gray-500 dark:text-slate-300">
                      {new Date(
                        selectedNotification.created_at
                      ).toLocaleString()}
                    </span>
                  </div>

                  {/* Notification Title (if exists) */}
                  {selectedNotification.title && (
                    <div className="bg-gradient-to-br from-white to-blue-50 dark:from-slate-700 dark:to-slate-600 rounded-xl p-4 border border-blue-200 dark:border-slate-500 shadow-sm">
                      <h3 className="text-xl font-bold text-gray-800 dark:text-white flex items-center gap-2">
                        <span className="material-icons text-primary-blue">
                          title
                        </span>
                        {selectedNotification.title}
                      </h3>
                    </div>
                  )}

                  {/* Notification Message */}
                  <div className="bg-gradient-to-br from-white to-blue-50 dark:from-slate-700 dark:to-slate-600 rounded-xl p-6 border border-blue-200 dark:border-slate-500 shadow-sm">
                    <h4 className="text-sm font-semibold text-gray-600 dark:text-slate-200 uppercase tracking-wide mb-3 flex items-center gap-2">
                      <span className="material-icons text-primary-blue text-sm">
                        message
                      </span>
                      Message
                    </h4>
                    <p className="text-gray-800 dark:text-white text-lg leading-relaxed whitespace-pre-wrap">
                      {selectedNotification.message}
                    </p>
                  </div>

                  {/* Additional Info (if exists) */}
                  {selectedNotification.notification_type && (
                    <div className="bg-gradient-to-br from-blue-50 to-teal-50 dark:from-teal-900 dark:to-blue-900 rounded-xl p-4 border border-blue-200 dark:border-teal-700">
                      <div className="flex items-center gap-2">
                        <span className="material-icons text-primary-blue">
                          info
                        </span>
                        <span className="text-sm font-semibold text-gray-700 dark:text-white">
                          Type:
                        </span>
                        <span className="text-sm text-gray-600 dark:text-slate-200">
                          {selectedNotification.notification_type}
                        </span>
                      </div>
                    </div>
                  )}
                </div>
              </div>

              {/* Modal Footer */}
              <div className="bg-slate-100 p-4 border-t border-blue-200 flex justify-end gap-3">
                <button
                  onClick={() => setShowNotificationModal(false)}
                  className="px-6 py-2 bg-gradient-to-r from-primary-blue to-primary-teal text-white font-semibold rounded-xl hover:shadow-lg transition-all duration-200 flex items-center gap-2"
                >
                  <span className="material-icons text-sm">check</span>
                  Close
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
      <div className="min-h-screen">
      {/* your other code */}
      <BibiChatbot />
    </div>
    </div>
  );
};

export default UserDashboard;
